                ->transform.basis_up = up;
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->transform.basis_forward =
                ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                    ->transform.position -
                ((AttachmentSample *)((char *)primary_samples + curve_sample_offset) -
