    cRFaceQuad *facequads = strip_mesh->facequads;
    Vector3 *vertices = strip_mesh->vertices;
    TransformMatrix kind42_transform;
    kind42_transform.Identity();

    int row, column;
    row = 0;
    if (segment_count >= 0)
    {
        int sample_offset = 0;
        do
        {
            column = 0;
            for (; column <= width_cells; ++column)
            {
                TransformMatrix *transform =
