                .transform.position;
        ((PathTemplateSample *)((char *)path->primary_samples + current_offset))[-1]
            .transform.basis_forward.Normalize();
        ((PathTemplateSample *)((char *)path->primary_samples + current_offset))[-1]
            .transform.basis_up.Cross(
                ((PathTemplateSample *)((char *)path->primary_samples +
                                        current_offset))[-1]
